def unique(pairs):
 value={}
 for k,v in pairs:
  if k in value:raise ValueError('duplicate component metadata key')
  value[k]=v
 return value

def metadata():
 p=COMPONENT/'source_states.json'
 if p.is_symlink() or not p.is_file():raise ValueError('exact component metadata required')
 value=json.loads(p.read_text(),object_pairs_hook=unique)
 if value!=EXPECTED_METADATA:raise ValueError('exact sync-ID metadata differs')
 patches=list(COMPONENT.glob('[0-9][0-9][0-9][0-9]-*.patch'))
 if len(patches)!=1 or patches[0].name!=PATCH or patches[0].is_symlink() or hashlib.sha256(patches[0].read_bytes()).hexdigest()!=PATCH_SHA256:raise ValueError('exact sync-ID patch differs')
 return value

def regular(root,relative):
 p=root/PROJECT/relative
 for parent in (p,*p.parents):
  if parent==root:break
  if parent.is_symlink():raise ValueError('source symlink refused: '+relative)
 st=p.stat()
 if not stat.S_ISREG(st.st_mode) or st.st_nlink!=1:raise ValueError('single regular source required: '+relative)
 return p.read_bytes()

def external_prerequisites(root):
 for row in EXPECTED_METADATA['external_prerequisites']:
  relative=row['relative'];p=root/relative
  for parent in (p,*p.parents):
   if parent==root:break
   if parent.is_symlink():raise ValueError('external source symlink refused: '+relative)
  st=p.stat()
  if not stat.S_ISREG(st.st_mode) or st.st_nlink!=1:raise ValueError('single external source required: '+relative)
  raw=p.read_bytes()
  if len(raw)!=row['bytes'] or hashlib.sha256(raw).hexdigest()!=row['sha256']:
   raise ValueError('exact external API prerequisite differs: '+relative)

def prerequisites(root):
 metadata();root=Path(root).resolve()
 external_prerequisites(root)
 for relative,sha,size in PREREQUISITES:
  raw=regular(root,relative)
  if len(raw)!=size or hashlib.sha256(raw).hexdigest()!=sha:raise ValueError('exact API/build prerequisite differs: '+relative)
 for relative,old,new in FILES:regular(root,relative)
 return validate(root)

def validate(root,require_patched=False):
 # Generic helper scratch contains only managed FILES, so sibling-only
 # prerequisites belong to the outer apply/check CLI, never this callback.
 metadata()
 return validate_component(root,PROJECT,REVISION,FILES,require_patched)

def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--source-root',type=Path,required=True)
 p.add_argument('--require-patched',action='store_true');p.add_argument('--check-prerequisites',action='store_true');a=p.parse_args()
 prerequisites(a.source_root)
 if a.check_prerequisites:return 0
 patched=validate(a.source_root,a.require_patched)
 print(json.dumps(dict(scope='exact sync-ID and accepted-prefix source configuration ONLY',patched=patched,compiled=False,
  actual_QEMU_positive_sync_ID_observed=False,actual_runtime_backend=None,accepted=False,onset_proven=False,first_artifact_behavior_gate_passed=False)))
 return 0
if __name__=='__main__':raise SystemExit(main())
